HOUR = 3_600_000


def make_candles(closes, interval_ms=HOUR, start_ms=1_700_000_000_000, wick=0.003, vol=100.0, vols=None):
    out = []
    prev = closes[0]
    for i, c in enumerate(closes):
        o = prev
        hi, lo = max(o, c) * (1 + wick), min(o, c) * (1 - wick)
        v = vols[i] if vols else vol
        out.append(Candle(start_ms + i * interval_ms, o, hi, lo, c, v, start_ms + (i + 1) * interval_ms - 1, v * c, 10))
        prev = c
    return out


def uptrend(n=300, start=100.0, drift=0.0015, amp=0.004, period=12):
    """Steady uptrend with small oscillations (pullbacks)."""
    return [start * (1 + drift) ** i * (1 + amp * math.sin(2 * math.pi * i / period)) for i in range(n)]


def downtrend(n=300, start=100.0, drift=-0.0015, amp=0.004, period=12):
    return uptrend(n, start, drift, amp, period)


